1590|static cJSON_bool print_array(const cJSON * const item, printbuffer * const output_buffer)
1591|{
1592|    unsigned char *output_pointer = NULL;
1593|    size_t length = 0;
1594|    cJSON *current_element = item->child;
1595|
1596|    if (output_buffer == NULL)
1597|    {
1598|        return false;
1599|    }
1600|
1601|    if (output_buffer->depth >= CJSON_NESTING_LIMIT)
1602|    {
1603|        return false; /* nesting is too deep */
1604|    }
1605|
1606|    /* Compose the output array. */
1607|    /* opening square bracket */
1608|    output_pointer = ensure(output_buffer, 1);
1609|    if (output_pointer == NULL)
1610|    {
1611|        return false;
1612|    }
1613|
1614|    *output_pointer = '[';
1615|    output_buffer->offset++;
1616|    output_buffer->depth++;
1617|
1618|    while (current_element != NULL)
1619|    {
1620|        if (!print_value(current_element, output_buffer))
1621|        {
1622|            return false;
1623|        }
1624|        update_offset(output_buffer);
1625|        if (current_element->next)
1626|        {
1627|            length = (size_t) (output_buffer->format ? 2 : 1);
1628|            output_pointer = ensure(output_buffer, length + 1);
1629|            if (output_pointer == NULL)
1630|            {
1631|                return false;
1632|            }
1633|            *output_pointer++ = ',';
1634|            if(output_buffer->format)
1635|            {
1636|                *output_pointer++ = ' ';
1637|            }
1638|            *output_pointer = '\0';
1639|            output_buffer->offset += length;
1640|        }
1641|        current_element = current_element->next;
1642|    }
1643|
1644|    output_pointer = ensure(output_buffer, 2);
1645|    if (output_pointer == NULL)
1646|    {
1647|        return false;
1648|    }
1649|    *output_pointer++ = ']';
1650|    *output_pointer = '\0';
1651|    output_buffer->depth--;
1652|
1653|    return true;
1654|}

