1774|/* Render an object to text. */
1775|static cJSON_bool print_object(const cJSON * const item, printbuffer * const output_buffer)
1776|{
1777|    unsigned char *output_pointer = NULL;
1778|    size_t length = 0;
1779|    cJSON *current_item = item->child;
1780|
1781|    if (output_buffer == NULL)
1782|    {
1783|        return false;
1784|    }
1785|
1786|    if (output_buffer->depth >= CJSON_NESTING_LIMIT)
1787|    {
1788|        return false; /* nesting is too deep */
1789|    }
1790|
1791|    /* Compose the output: */
1792|    length = (size_t) (output_buffer->format ? 2 : 1); /* fmt: {\n */
1793|    output_pointer = ensure(output_buffer, length + 1);
1794|    if (output_pointer == NULL)
1795|    {
1796|        return false;
1797|    }
1798|
1799|    *output_pointer++ = '{';
1800|    output_buffer->depth++;
1801|    if (output_buffer->format)
1802|    {
1803|        *output_pointer++ = '\n';
1804|    }
1805|    output_buffer->offset += length;
1806|
1807|    while (current_item)
1808|    {
1809|        if (output_buffer->format)
1810|        {
1811|            size_t i;
1812|            output_pointer = ensure(output_buffer, output_buffer->depth);
1813|            if (output_pointer == NULL)
1814|            {
1815|                return false;
1816|            }
1817|            for (i = 0; i < output_buffer->depth; i++)
1818|            {
1819|                *output_pointer++ = '\t';
1820|            }
1821|            output_buffer->offset += output_buffer->depth;
1822|        }
1823|
1824|        /* print key */
1825|        if (!print_string_ptr((unsigned char*)current_item->string, output_buffer))
1826|        {
1827|            return false;
1828|        }
1829|        update_offset(output_buffer);
1830|
1831|        length = (size_t) (output_buffer->format ? 2 : 1);
1832|        output_pointer = ensure(output_buffer, length);
1833|        if (output_pointer == NULL)
1834|        {
1835|            return false;
1836|        }
1837|        *output_pointer++ = ':';
1838|        if (output_buffer->format)
1839|        {
1840|            *output_pointer++ = '\t';
1841|        }
1842|        output_buffer->offset += length;
1843|
1844|        /* print value */
1845|        if (!print_value(current_item, output_buffer))
1846|        {
1847|            return false;
1848|        }
1849|        update_offset(output_buffer);
1850|
1851|        /* print comma if not last */
1852|        length = ((size_t)(output_buffer->format ? 1 : 0) + (size_t)(current_item->next ? 1 : 0));
1853|        output_pointer = ensure(output_buffer, length + 1);
1854|        if (output_pointer == NULL)
1855|        {
1856|            return false;
1857|        }
1858|        if (current_item->next)
1859|        {
1860|            *output_pointer++ = ',';
1861|        }
1862|
1863|        if (output_buffer->format)
1864|        {
1865|            *output_pointer++ = '\n';
1866|        }
1867|        *output_pointer = '\0';
1868|        output_buffer->offset += length;
1869|
1870|        current_item = current_item->next;
1871|    }
1872|
1873|    output_pointer = ensure(output_buffer, output_buffer->format ? (output_buffer->depth + 1) : 2);
1874|    if (output_pointer == NULL)
1875|    {
1876|        return false;
1877|    }
1878|    if (output_buffer->format)
1879|    {
1880|        size_t i;
1881|        for (i = 0; i < (output_buffer->depth - 1); i++)
1882|        {
1883|            *output_pointer++ = '\t';
1884|        }
1885|    }
1886|    *output_pointer++ = '}';
1887|    *output_pointer = '\0';
1888|    output_buffer->depth--;
1889|
1890|    return true;
