660|/* parse 4 digit hexadecimal number */
661|static unsigned parse_hex4(const unsigned char * const input)
662|{
663|    unsigned int h = 0;
664|    size_t i = 0;
665|
666|    for (i = 0; i < 4; i++)
667|    {
668|        /* parse digit */
669|        if ((input[i] >= '0') && (input[i] <= '9'))
670|        {
671|            h += (unsigned int) input[i] - '0';
672|        }
